 {'id': 'record_pattern_ctor__refs_excl',
  'files': {},
  'args': ['lsp'],
  'lsp': [{'jsonrpc': '2.0', 'id': 1, 'method': 'initialize', 'params': {}},
          {'jsonrpc': '2.0', 'method': 'initialized', 'params': {}},
          {'jsonrpc': '2.0',
           'method': 'textDocument/didOpen',
           'params': {'textDocument': {'uri': 'untitled:rich.pyfun',
                                       'languageId': 'pyfun',
                                       'version': 1,
                                       'text': '## Units used below.\n'
                                               'measure m\n'
                                               'measure s\n'
                                               '## A colour.\n'
                                               'type Color = Red | Green | Blue\n'
                                               '## A boxed reading.\n'
                                               'type Reading = { label: string, value: float, tags: List '
                                               'string }\n'
                                               '## Square root, from Python.\n'
                                               'extern root2 : float -> float = math.sqrt\n'
                                               'let (|Small|Large|) n = if n < 10 then Small else Large\n'
                                               'module Stats =\n'
                                               '  let scale = 2\n'
                                               '  let double x = x * scale\n'
                                               'let base = 3\n'
                                               '## Adds two numbers.\n'
                                               'let add x y =\n'
                                               '  let total = x + y\n'
                                               '  total * base\n'
                                               'let classify c =\n'
                                               '  match c:\n'
                                               '    case Red: "r"\n'
                                               '    case Green | Blue as other: "gb"\n'
                                               'let size k =\n'
                                               '  match k:\n'
                                               '    case Small: f"small {k}"\n'
                                               '    case Large: "large"\n'
                                               'let r = Reading { label = "a", value = 2.0, tags = ["x"] }\n'
                                               'let r2 = { r with label = "b" }\n'
                                               'let dist = 12.0<m>\n'
                                               'let speed = dist / 4.0<s>\n'
                                               'let lbl rd =\n'
                                               '  match rd:\n'
                                               '    case Reading { label, value, tags }: label\n'
                                               'let firsts xs =\n'
                                               '  match xs:\n'
                                               '    case [h, *rest] as whole: h + List.len rest\n'
                                               '    case []: 0\n'
                                               'let checked n =\n'
                                               '  result {\n'
                                               '    let! v = if n > 0 then Ok n else Error "neg"\n'
                                               '    return v + base\n'
                                               '  }\n'
                                               'let inc = fun q -> q + Stats.double base\n'
                                               'let (pa, pb) = (add 1 2, Stats.scale)\n'
                                               'let mut counter = 0\n'
                                               'let bump u =\n'
                                               '  counter <- counter + 1\n'
                                               '  counter\n'
                                               'let msg = f"{pa} and {pb}"\n'
                                               'let piped = [1, 2, 3] |> List.map inc |> List.fold (+) 0\n'
                                               'let rt = root2 16.0\n'
                                               'print f"{classify Green} {size 3} {lbl r2} {firsts [4, 5]} '
                                               '{msg} {piped} {rt} {bump ()} {r.value}"\n'}}},
          {'jsonrpc': '2.0',
           'id': 2,
           'method': 'textDocument/references',
           'params': {'textDocument': {'uri': 'untitled:rich.pyfun'},
                      'position': {'line': 32, 'character': 9},
                      'context': {'includeDeclaration': False}}},
          {'jsonrpc': '2.0', 'id': 99, 'method': 'shutdown'},
          {'jsonrpc': '2.0', 'method': 'exit'}]},
