@pytest.mark.parametrize("case", CASES, ids=[c["id"] for c in CASES])
def test_navigation_per_symbol_site(run, workdir, case):
    """CATCHES: a site kind that resolves to the wrong symbol, range, type, effect or doc,
    or a rename/references answer that differs from the reference server."""
    S.check(run, workdir, case, __file__)
